import subprocess, re, collections
d = subprocess.run(['git','show','e5c881b','--','IP/STD_cell/ics55_LLSC_H7C_V1p10C100/ics55_LLSC_H7CH/lef/ics55_LLSC_H7CH_ecos.lef'],capture_output=True,text=True).stdout
pin=None; pairs=collections.Counter(); macros=[]
ctx=''
for line in d.splitlines():
    if line.startswith('@@'): ctx=line
    m=re.match(r'\s*PIN (\S+)',line)
    if m: pin=m.group(1)
    if re.match(r'-\s+DIRECTION',line): old=line.split()[2]
    if re.match(r'\+\s+DIRECTION',line):
        new=line.split()[2]
        pairs[(pin,old,new)]+=1
        mm=re.search(r'MACRO (\S+)',ctx)
        if mm: macros.append((mm.group(1),pin,old,new))
for k,v in sorted(pairs.items()): print(k,v)
print('--- affected macros (H7CH):',len(set(m[0] for m in macros)))
print('--- INPUT->OUTPUT cases:')
for m in macros:
    if m[2]=='INPUT': print(m)

